def clean(df):
    df = df.drop_duplicates()
    df['Region'] = df['Region'].str.strip().str.title()
    df = df[df['Quantity'] >= 1]
    return df

def answer(df):
    electronics = df[df['Category'] == 'Electronics']
    grouped = electronics.groupby('Region')['Revenue'].sum()
    return grouped.to_dict()
